import {cleanAppearance} from './scanner-appearance.js';
import {library,defaults,approaches} from './data.js';
import {cleanSettings,settingsErrors,defaultSettings} from './scanner-settings.js';
export const STORAGE_KEY='soltech.signature.workspace.v1';
const copy=v=>JSON.parse(JSON.stringify(v));
const text=(v,max=180)=>typeof v==='string'?v.slice(0,max):'';
const allowed=(v,list,fallback)=>list.includes(v)?v:fallback;
const identifier=v=>typeof v==='string'&&/^[a-z0-9-]{1,90}$/.test(v);
export function cleanFields(value={}){return {...cleanAppearance(value),name:text(value.name,50),description:text(value.description),focus:allowed(value.focus,approaches.map(a=>a[0]),defaults.focus),liquidity:allowed(value.liquidity,['Any liquidity','Established','Higher liquidity'],defaults.liquidity),age:allowed(value.age,['Any age','At least 7 days','At least 30 days','At least 90 days'],defaults.age),concentration:typeof value.concentration==='boolean'?value.concentration:true,liquidityCheck:typeof value.liquidityCheck==='boolean'?value.liquidityCheck:true,filters:cleanSettings(value.filters,value)};}
function cleanScanner(value){if(!value||!identifier(value.id)||!value.name?.trim())return null;const source=library.find(s=>s.id===value.sourceId);return {id:value.id,sourceId:source?.id||null,kind:value.kind==='library'&&source?'library':'custom',placement:value.placement==='saved'?'saved':'active',...cleanFields(value),savedAt:text(value.savedAt,40),updatedAt:text(value.updatedAt,40)};}
function cleanSeen(value){if(!value||typeof value!=='object'||Array.isArray(value))return {};return Object.fromEntries(Object.entries(value).filter(([id,list])=>identifier(id)&&Array.isArray(list)).map(([id,list])=>[id,[...new Set(list.filter(identifier))].slice(0,500)]));}
function cleanDraft(value){if(!value?.fields)return null;return {flowVersion:2,purposeChosen:value.flowVersion===2?value.purposeChosen!==false:true,autoName:value.autoName===true,autoAge:value.autoAge===true,mode:allowed(value.mode,['new','customize','edit'],'new'),editingId:identifier(value.editingId)?value.editingId:null,sourceId:library.some(s=>s.id===value.sourceId)?value.sourceId:null,step:value.flowVersion===2?allowed(value.step,[1,2,3],1):value.step===2?3:2,fields:cleanFields({...value.fields,sourceId:value.sourceId})};}
function initial(){return {schemaVersion:1,homeSetup:0,savedScanners:[],seenFindings:{},draft:null,view:{query:'',filter:'all',selected:'balanced'},removed:null};}
export function createWorkspace(storage){
 let state=initial(),issue=null,blocked=false,lastStored=null;
 try{const raw=storage.getItem(STORAGE_KEY);lastStored=raw;if(raw){const data=JSON.parse(raw);if(data.schemaVersion!==1||!Array.isArray(data.savedScanners))throw Error('Unrecognized saved data');state={...initial(),homeSetup:data.homeSetup===1?1:0,savedScanners:data.savedScanners.map(cleanScanner).filter(Boolean),seenFindings:cleanSeen(data.seenFindings),draft:cleanDraft(data.draft),view:{query:text(data.view?.query,100),filter:'all',selected:allowed(data.view?.selected,library.map(s=>s.id),'balanced')},removed:cleanScanner(data.removed)};if(state.savedScanners.length!==data.savedScanners.length)throw Error('Invalid scanner');}}
 catch(error){issue='read';blocked=true;}
 const commit=()=>{if(blocked)return false;try{if(storage.getItem(STORAGE_KEY)!==lastStored){issue='conflict';return false;}const serialized=JSON.stringify(state);storage.setItem(STORAGE_KEY,serialized);lastStored=serialized;issue=null;return true;}catch(error){issue='write';return false;}};
 return {
  get state(){return state;},get issue(){return issue;},persist:commit,
  prepareWorkspace(){if(blocked||state.homeSetup===1)return;state.homeSetup=1;const oldNames={balanced:'Balanced discovery',momentum:'Early momentum'};for(const scanner of state.savedScanners){if(scanner.kind==='library'&&scanner.name===oldNames[scanner.sourceId]){const source=library.find(s=>s.id===scanner.sourceId);scanner.name=source.name;scanner.description=source.description;}}commit();},
  markFindingSeen(scannerId,coinId){if(!state.savedScanners.some(scanner=>scanner.id===scannerId)||!identifier(coinId))return false;const seen=state.seenFindings[scannerId]||[];if(seen.includes(coinId))return !issue;state.seenFindings[scannerId]=[...seen,coinId];return commit();},
  setView(view){state.view={...state.view,...view};commit();},
  beginDraft({mode='new',scanner=null}={}){state.draft={flowVersion:2,purposeChosen:!!scanner,autoName:!scanner,autoAge:!scanner,mode,editingId:mode==='edit'?scanner.id:null,sourceId:scanner?(library.some(s=>s.id===scanner.sourceId)?scanner.sourceId:library.some(s=>s.id===scanner.id)?scanner.id:null):null,step:scanner?2:1,fields:cleanFields(scanner?{...scanner.criteria,...scanner,name:mode==='customize'?`${scanner.name} · Mine`:scanner.name}:{...defaults,name:'My first scanner',description:'',filters:{...defaultSettings('projects'),ageMax:'24',matchMode:'direct',riskLevels:['lower','caution','unknown']}})};commit();return state.draft;},
  choosePurpose(type){if(!state.draft||!['public','projects','market'].includes(type))return;const f=state.draft.fields,suggestName=state.draft.mode==='new'&&state.draft.autoName;const initialChoice=state.draft.mode==='new'&&state.draft.autoAge;state.draft.purposeChosen=true;state.draft.fields=cleanFields({...f,filters:{...f.filters,...(initialChoice?{ageMax:type==='projects'?'24':''}:{}),type},name:suggestName?{public:'My X scanner',projects:'My new coin scanner',market:'My market scanner'}[type]:f.name});commit();},
  updateDraft(fields){if(!state.draft)return;if(Object.hasOwn(fields,'name'))state.draft.autoName=false;if(fields.filters&&(fields.filters.ageMax!==state.draft.fields.filters.ageMax||fields.filters.ageMin!==state.draft.fields.filters.ageMin||fields.filters.ageBasis!==state.draft.fields.filters.ageBasis))state.draft.autoAge=false;state.draft.fields=cleanFields({...state.draft.fields,...fields});commit();},
  step(value){if(state.draft){state.draft.step=allowed(value,[1,2,3],1);commit();}},
  discardDraft(){state.draft=null;commit();},
  saveLibrary(id,placement='active'){const source=library.find(s=>s.id===id);if(!source)return null;const existing=state.savedScanners.find(s=>s.kind==='library'&&s.sourceId===id);if(existing)return {scanner:existing,existing:true,persisted:!issue};const now=new Date().toISOString();const scanner={id:`saved-${id}-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,sourceId:id,kind:'library',placement:placement==='saved'?'saved':'active',...cleanFields({...source.criteria,name:source.name,description:source.description}),savedAt:now,updatedAt:now};state.savedScanners.push(scanner);return {scanner,existing:false,persisted:commit()};},
  saveDraft(){const draft=state.draft;if(!draft?.fields.name.trim()||Object.keys(settingsErrors(draft.fields.filters)).length)return null;const existing=state.savedScanners.find(s=>s.id===draft.editingId);const now=new Date().toISOString();const scanner={id:existing?.id||`personal-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,sourceId:draft.sourceId,kind:'custom',placement:existing?.placement||'saved',...cleanFields(draft.fields),name:draft.fields.name.trim(),savedAt:existing?.savedAt||now,updatedAt:now};const index=state.savedScanners.findIndex(s=>s.id===scanner.id);if(index>=0)state.savedScanners[index]=scanner;else state.savedScanners.push(scanner);state.draft=null;return {scanner,existing:!!existing,recovered:draft.mode==='edit'&&!existing,persisted:commit()};},
  move(id,placement){const scanner=state.savedScanners.find(s=>s.id===id);if(!scanner||!['active','saved'].includes(placement))return null;scanner.placement=placement;scanner.updatedAt=new Date().toISOString();commit();return scanner;},
  remove(id){const scanner=state.savedScanners.find(s=>s.id===id);if(!scanner)return;state.removed=copy(scanner);state.savedScanners=state.savedScanners.filter(s=>s.id!==id);commit();return scanner;},
  undo(){if(!state.removed)return null;const scanner=state.removed;if(!state.savedScanners.some(s=>s.id===scanner.id))state.savedScanners.push(scanner);state.removed=null;commit();return scanner;},
  retry(){if(blocked)return false;return commit();},
  export(){return JSON.stringify(state,null,2);}
 };
}
